const items=[{id:1,name:'Жакет «Сдвиг»',price:18900,cat:'outer',note:'Смещённая линия плеча / Чёрный',img:'assets/hero.png',fit:'contain'},{id:2,name:'Пальто «Контур»',price:24900,cat:'outer',note:'Свободный силуэт / Графит',img:'https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=700&q=85'},{id:3,name:'Топ «Диагональ»',price:6900,cat:'base',note:'Асимметричный крой / Молочный',img:'https://images.unsplash.com/photo-1551163943-3f6a855d1153?auto=format&fit=crop&w=700&q=85'},{id:4,name:'Юбка «Разрез»',price:12900,cat:'bottom',note:'Ломаная линия / Чёрный',img:'https://images.unsplash.com/photo-1539109136881-3be0616acf4b?auto=format&fit=crop&w=700&q=85'}];
const money=n=>n.toLocaleString('ru-RU')+' ₽';let cart=[];try{cart=JSON.parse(localStorage.getItem('asimetria-bag')||'[]')}catch{};const products=document.querySelector('#products');function render(filter='all'){products.innerHTML=items.filter(p=>filter==='all'||p.cat===filter).map(p=>`<button class="product" data-id="${p.id}" aria-label="Открыть ${p.name}"><div class="product-image"><img src="${p.img}" alt="${p.name}" loading="lazy" style="object-fit:${p.fit||'cover'}"><span>↗</span></div><div class="product-info">${p.name}<span>${money(p.price)}</span></div><small>${p.note}</small></button>`).join('')}render();document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelector('.filters .active').classList.remove('active');b.classList.add('active');render(b.dataset.filter)});
const pd=document.querySelector('#productDialog'),bd=document.querySelector('#bagDialog');products.onclick=e=>{const b=e.target.closest('[data-id]');if(!b)return;const p=items.find(p=>p.id===+b.dataset.id);document.querySelector('#productContent').innerHTML=`<div class="detail"><img src="${p.img}" alt="${p.name}" style="object-fit:${p.fit||'cover'}"><div><h2>${p.name}</h2><p>${money(p.price)}</p><p>${p.note}</p><p>Экспериментальная форма для собственного ритма.</p><label>Выберите размер</label><div class="sizes">${['XS','S','M','L'].map(s=>`<button type="button">${s}</button>`).join('')}</div><button class="primary" id="add">В сумку</button><p><small>Демонстрационный товар</small></p></div></div>`;let size=null;pd.querySelectorAll('.sizes button').forEach(b=>b.onclick=()=>{pd.querySelector('.selected')?.classList.remove('selected');b.classList.add('selected');size=b.textContent});pd.querySelector('#add').onclick=()=>{if(!size){toast('Сначала выберите размер');return}cart.push({id:p.id,size});save();pd.close();toast('Добавлено в сумку')};pd.showModal()};
function save(){try{localStorage.setItem('asimetria-bag',JSON.stringify(cart))}catch{}document.querySelector('#count').textContent=`(${cart.length})`}save();function bag(){document.querySelector('#bagContent').innerHTML=cart.length?cart.map((x,i)=>{const p=items.find(p=>p.id===x.id);return `<div class="cart-row"><img src="${p.img}" alt="${p.name}"><div>${p.name}<small>Размер ${x.size} / ${money(p.price)}</small></div><button data-remove="${i}" aria-label="Удалить ${p.name}">×</button></div>`}).join('')+`<h3>Итого: ${money(cart.reduce((t,x)=>t+items.find(p=>p.id===x.id).price,0))}</h3><p>Это демонстрационная сумка. Покупки и оплата пока недоступны.</p>`:'<p>Пока пусто. Найди свою форму в коллекции.</p><button class="primary" id="toCatalog">Смотреть коллекцию</button>';document.querySelector('#toCatalog')?.addEventListener('click',()=>{bd.close();document.querySelector('#catalog').scrollIntoView({behavior:'smooth'})});bd.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart.splice(+b.dataset.remove,1);save();bag()})}document.querySelector('#bagButton').onclick=()=>{bag();bd.showModal()};document.querySelector('#infoButton').onclick=()=>document.querySelector('#infoDialog').showModal();document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});let toastTimer;function toast(s){const el=document.querySelector('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2400)}
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const hero=document.querySelector('.hero');if(!reduced&&matchMedia('(pointer:fine)').matches){hero.addEventListener('pointermove',e=>{const x=e.clientX/innerWidth-.5,y=e.clientY/innerHeight-.5;hero.querySelectorAll('h1 span').forEach((l,i)=>{l.style.transform=`translate(${x*(i-4)*7}px,${y*(i%2?12:-12)}px) rotate(${x*(i-4)*.4}deg)`})});hero.addEventListener('pointerleave',()=>hero.querySelectorAll('h1 span').forEach(l=>l.style.transform='none'))}let ticking=false;function move(){const section=document.querySelector('.chaos');const r=section.getBoundingClientRect(),p=Math.max(0,Math.min(1,-r.top/(section.offsetHeight-innerHeight)));document.querySelectorAll('.shot').forEach((s,i)=>{const rotations=[-9,12,-7];s.style.transform=`translateY(${Math.sin(p*Math.PI)*[45,-70,40][i]}px) rotate(${rotations[i]*Math.sin(p*Math.PI)}deg)`});ticking=false}if(!reduced){addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(move);ticking=true}},{passive:true});move()}
